namespace GroceryStore.Domain.Entities;

public sealed class PosOrderItem
{ private PosOrderItem() { Name = string.Empty; } public PosOrderItem(Guid posOrderId, Guid productVariantId, string name, decimal quantity, decimal unitPrice) { if (quantity <= 0 || unitPrice < 0) throw new ArgumentOutOfRangeException(nameof(quantity)); PosOrderItemId = Guid.NewGuid(); PosOrderId = posOrderId; ProductVariantId = productVariantId; Name = name; Quantity = quantity; UnitPrice = unitPrice; LineTotal = quantity * unitPrice; } public Guid PosOrderItemId { get; private set; } public Guid PosOrderId { get; private set; } public Guid ProductVariantId { get; private set; } public string Name { get; private set; } public decimal Quantity { get; private set; } public decimal UnitPrice { get; private set; } public decimal LineTotal { get; private set; } }
